```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

const config = new pulumi.Config();
const env = config.get("env") || "dev";
const region = config.get("region") || "us-east-1";

// ─── S3 Bucket ────────────────────────────────────────────────────────────────

const bucket = new aws.s3.Bucket("app-bucket", {
    bucket: `myapp-assets-${env}`,
    versioning: { enabled: true },
    serverSideEncryptionConfiguration: {
        rule: [
            {
                applyServerSideEncryptionByDefault: {
                    sseAlgorithm: "AES256",
                },
            },
        ],
    },
    tags: { Environment: env, Project: "myapp" },
});

// Block all public access
new aws.s3.BucketPublicAccessBlock("app-bucket-block", {
    bucket: bucket.id,
    blockPublicAcls: true,
    blockPublicPolicy: true,
    ignorePublicAcls: true,
    restrictPublicBuckets: true,
});

// ─── FIX 1: Replace async/await with .apply() ───────────────────────────────
//
// BEFORE (broken):
//   async function getBucketUrl(arn: pulumi.Output<string>) {
//       const resolved = await arn;          // ← crashes at preview
//       return `https://s3.${region}.amazonaws.com/${resolved}`;
//   }
//   const bucketUrl = getBucketUrl(bucket.arn);  // ← returns Promise<string>
//
// AFTER (correct):
//   Use .apply() to transform the Output synchronously within Pulumi's
//   dependency graph. This returns a new Output<string>.

const bucketUrl = bucket.arn.apply(arn =>
    `https://s3.${region}.amazonaws.com/${arn}`
);

// ─── FIX 2: Replace pulumi.output("literal") with config.requireSecret() ────
//
// BEFORE (broken):
//   const dbPassword = pulumi.output("plain-text-password");
//     ↑ Wraps a plain string in an Output — no secret registration,
//       leaks the value into the program text and into state as plaintext.
//
// AFTER (correct):
//   config.requireSecret() reads a Pulumi-encrypted secret from the stack
//   config (stored as a ciphertext blob in the backend). The returned
//   Output<string> is marked as a secret so it is never printed in
//   `pulumi preview` or `pulumi up` output.

const dbPassword = config.requireSecret("db-password");

// ─── RDS Instance ─────────────────────────────────────────────────────────────

const isProd = env === "prod";

const db = new aws.rds.Instance("app-db", {
    instanceClass: isProd ? "db.t3.medium" : "db.t3.micro",
    engine: "postgres",
    engineVersion: "16.1",
    allocatedStorage: 20,
    dbName: "appdb",
    username: "app-user",
    password: dbPassword,
    skipFinalSnapshot: !isProd,
    deletionProtection: true,
    publiclyAccessible: false,
    backupRetention: 7,
    multiAz: isProd,
    storageEncrypted: isProd,
    tags: { Environment: env, Project: "myapp" },
});

// ─── Outputs ──────────────────────────────────────────────────────────────────

// bucketUrl is now a proper pulumi.Output<string> — safe to export.
export const bucketEndpoint = bucketUrl;

export const dbEndpoint = db.endpoint;
```

## Summary of fixes

| # | Defect | Root cause | Fix |
|---|--------|-----------|-----|
| 1 | `async function` + `await` on an `Output` | Pulumi `Output`s are not Promises; `await` on one resolves to the *object* (not the wrapped value) at preview time, causing a crash or silent wrong value. | Replaced with `bucket.arn.apply(arn => …)` which is the canonical way to derive one `Output` from another. The result is a proper `pulumi.Output<string>`. |
| 2 | `pulumi.output("plain-text-password")` | Wraps a plaintext literal in an `Output` shell. The value is committed to source control and appears unencrypted in state. No Pulumi secret tracking is applied. | Replaced with `config.requireSecret("db-password")`. The value lives in `dev.yaml`/`prod.yaml` as a `secure:` field (encrypted by the Pulumi backend), and the returned `Output` carries the secret flag so it's redacted in CLI output. |

### Stack config example (`prod.yaml`)

```yaml
config:
  myapp:env: prod
  myapp:region: us-east-1
  myapp:db-password:
    secure: AAABAA…(encrypted by `pulumi config set --secret`)
```

Set the secret once with:

```bash
pulumi config set --secret db-password '<value>'
```

After that the plaintext is never present in the repo — only the ciphertext blob is.
